from jsonb_to_recordset($q$[{"id":2525,"materia":"port","nivel":1,"enunciado":"Em “Choveu muito; por isso, o jogo foi adiado”, a expressão “por isso” indica:","opcoes":["Consequência","Causa","Concessão","Condição"],"explicacao":"A segunda oração mostra o efeito da chuva."},{"id":2526,"materia":"port","nivel":1,"enunciado":"Em “Embora estivesse cansado, continuou estudando”, a conjunção “embora” indica:","opcoes":["Concessão","Causa","Conclusão","Finalidade"],"explicacao":"Concessão: um fato contrário que não impede o outro."},{"id":2527,"materia":"port","nivel":1,"enunciado":"Qual frase usa corretamente “mal” e “mau”?","opcoes":["Ele se sentiu mal com o mau tempo","Ele se sentiu mau com o mal tempo","Ele se sentiu mau com o mau tempo","Ele se sentiu mal com o mal tempo"],"explicacao":"Mal se opõe a bem; mau se opõe a bom."},{"id":2528,"materia":"port","nivel":1,"enunciado":"Em “Assisti ao filme ontem”, o verbo “assistir” tem o sentido de:","opcoes":["Ver","Ajudar","Morar","Caber"],"explicacao":"No sentido de ver, “assistir” pede a preposição “a”."},{"id":2529,"materia":"port","nivel":1,"enunciado":"Qual é o feminino de “cônsul”?","opcoes":["Consulesa","Cônsula","Consuleira","Consulina"],"explicacao":"Assim como “duque/duquesa” e “barão/baronesa”."},{"id":2530,"materia":"port","nivel":1,"enunciado":"Em “Vende-se esta casa”, o sujeito é:","opcoes":["Esta casa","Indeterminado","Oculto","Inexistente"],"explicacao":"É voz passiva sintética: “Esta casa é vendida”."},{"id":2531,"materia":"const","nivel":1,"enunciado":"O número de deputados federais de cada estado é proporcional à:","opcoes":["População","Área territorial","Arrecadação de impostos","Quantidade de municípios"],"explicacao":"Mínimo de 8 e máximo de 70 por estado (art. 45)."},{"id":2532,"materia":"const","nivel":1,"enunciado":"Qual destes cargos é privativo de brasileiro nato?","opcoes":["Oficial das Forças Armadas","Governador de estado","Senador","Ministro do TCU"],"explicacao":"Art. 12, § 3º. Para senador, só o Presidente do Senado precisa ser nato."},{"id":2533,"materia":"const","nivel":1,"enunciado":"A casa do Congresso que representa os estados e o DF é o:","opcoes":["Senado Federal","Câmara dos Deputados","Tribunal de Contas da União","Conselho da República"],"explicacao":"A Câmara representa o povo."},{"id":2534,"materia":"const","nivel":1,"enunciado":"Nos municípios, o Poder Legislativo é exercido pela:","opcoes":["Câmara Municipal","Assembleia Legislativa","Prefeitura","Câmara dos Deputados"],"explicacao":"Composta por vereadores."},{"id":2535,"materia":"const","nivel":1,"enunciado":"O plebiscito é convocado:","opcoes":["Antes do ato, para o povo decidir sobre ele","Depois da lei aprovada, para que o povo a ratifique ou não","Apenas para eleger o Presidente","Somente por ordem do STF"],"explicacao":"O referendo é posterior ao ato."},{"id":2536,"materia":"const","nivel":1,"enunciado":"É vedado à União, aos estados, ao DF e aos municípios:","opcoes":["Estabelecer cultos religiosos ou subvencioná-los","Cobrar tributos","Criar e manter escolas públicas de ensino fundamental","Manter forças policiais"],"explicacao":"Art. 19, I: o Estado brasileiro é laico."},{"id":2537,"materia":"adm","nivel":1,"enunciado":"A administração pública indireta inclui, entre outras:","opcoes":["Autarquias e fundações públicas","Ministérios, secretarias e seus departamentos internos","Câmaras municipais","Partidos políticos"],"explicacao":"Também empresas públicas e sociedades de economia mista."},{"id":2538,"materia":"adm","nivel":1,"enunciado":"Os bens das autarquias são, em regra:","opcoes":["Públicos e impenhoráveis","Privados e penhoráveis","Bens sem dono","Bens dos próprios servidores"],"explicacao":"Autarquias são pessoas jurídicas de direito público."},{"id":2539,"materia":"adm","nivel":1,"enunciado":"Pela Lei 8.112/1990, a reintegração é:","opcoes":["O retorno do servidor cuja demissão foi anulada","O retorno do aposentado à atividade","A mudança de cargo por limitação física ou mental comprovada","O retorno do servidor em disponibilidade"],"explicacao":"As outras são reversão, readaptação e aproveitamento."},{"id":2540,"materia":"adm","nivel":1,"enunciado":"O poder de polícia permite à Administração:","opcoes":["Limitar direitos individuais em favor do interesse público","Prender pessoas sem ordem judicial em qualquer situação","Criar leis penais","Julgar crimes comuns"],"explicacao":"Ex.: fiscalização sanitária e licença para construir."},{"id":2541,"materia":"adm","nivel":1,"enunciado":"Pela Lei 8.112/1990, a remoção é o deslocamento do servidor:","opcoes":["No mesmo quadro, com ou sem mudança de sede","Para outro cargo de outra carreira, por concurso interno","Para fora do serviço público","Para a aposentadoria"],"explicacao":"Art. 36 da Lei 8.112/1990."},{"id":2542,"materia":"adm","nivel":1,"enunciado":"Distribuir competências entre órgãos da mesma pessoa jurídica é a:","opcoes":["Desconcentração","Descentralização","Privatização","Delegação legislativa"],"explicacao":"Na descentralização, cria-se ou usa-se outra pessoa jurídica."},{"id":2543,"materia":"pen","nivel":1,"enunciado":"Patrocinar interesse privado perante a Administração, valendo-se da condição de funcionário, é:","opcoes":["Advocacia administrativa","Tráfico de influência","Prevaricação","Peculato"],"explicacao":"Art. 321 do Código Penal."},{"id":2544,"materia":"pen","nivel":1,"enunciado":"Quem age para salvar de perigo atual, que não provocou, direito próprio ou alheio, atua em:","opcoes":["Estado de necessidade","Legítima defesa","Exercício regular de direito","Estrito cumprimento do dever legal"],"explicacao":"Art. 24 do Código Penal."},{"id":2545,"materia":"pen","nivel":1,"enunciado":"Em regra, o crime tentado é punido com a pena do consumado reduzida de:","opcoes":["1/3 a 2/3","1/6 a 1/3","Metade, sempre","2/3 a 3/4"],"explicacao":"Art. 14, parágrafo único."},{"id":2546,"materia":"pen","nivel":1,"enunciado":"Reparar o dano até o recebimento da denúncia, em crime sem violência ou grave ameaça, gera:","opcoes":["Redução da pena de 1/3 a 2/3","Extinção da punibilidade","Perdão judicial","Aumento da pena"],"explicacao":"É o arrependimento posterior (art. 16)."},{"id":2547,"materia":"pen","nivel":1,"enunciado":"Pelo Código Penal, a embriaguez voluntária ou culposa:","opcoes":["Não exclui a imputabilidade","Exclui sempre a pena","Reduz a pena pela metade em qualquer crime","Torna o crime culposo"],"explicacao":"Art. 28, II. Só a embriaguez completa por caso fortuito isenta de pena."},{"id":2548,"materia":"pen","nivel":1,"enunciado":"O furto praticado durante o repouso noturno tem a pena:","opcoes":["Aumentada de 1/3","Diminuída de 1/3","Dobrada","Inalterada"],"explicacao":"Art. 155, § 1º, do Código Penal."},{"id":2549,"materia":"ppen","nivel":1,"enunciado":"O flagrante em que o agente é perseguido logo após o crime chama-se:","opcoes":["Impróprio (quase flagrante)","Próprio","Presumido","Preparado"],"explicacao":"Art. 302, III, do CPP."},{"id":2550,"materia":"ppen","nivel":1,"enunciado":"A ação penal pública condicionada depende de:","opcoes":["Representação do ofendido ou requisição do Ministro da Justiça","Queixa-crime do ofendido","Autorização do delegado","Pedido do próprio réu"],"explicacao":"Sem a condição, o MP não pode denunciar."},{"id":2551,"materia":"ppen","nivel":1,"enunciado":"A prisão em flagrante deve ser comunicada imediatamente ao juiz, ao MP e:","opcoes":["À família do preso ou a pessoa por ele indicada","Ao prefeito da cidade","À imprensa local","Ao empregador do preso"],"explicacao":"Art. 306 do CPP."},{"id":2552,"materia":"ppen","nivel":1,"enunciado":"Em regra, o auto de prisão em flagrante é lavrado pelo:","opcoes":["Delegado de polícia","Juiz","Promotor de justiça","Oficial de justiça"],"explicacao":"Art. 304 do CPP."},{"id":2553,"materia":"ppen","nivel":1,"enunciado":"Com o réu solto, o prazo para o MP oferecer denúncia é de:","opcoes":["15 dias","5 dias","30 dias","10 dias"],"explicacao":"Art. 46 do CPP."},{"id":2554,"materia":"ppen","nivel":1,"enunciado":"A prisão preventiva é decretada:","opcoes":["Pelo juiz, a pedido do MP, do querelante ou da polícia","Pelo delegado, de ofício, durante o inquérito policial","Pelo promotor, sem ordem judicial","Por qualquer policial militar"],"explicacao":"Art. 311 do CPP, após a Lei 13.964/2019."},{"id":2555,"materia":"leg","nivel":1,"enunciado":"Pela Lei de Drogas, cultivar pequena quantidade de planta para consumo pessoal é:","opcoes":["Equiparado ao porte para uso (art. 28)","Tráfico de drogas","Associação para o tráfico","Sempre fato atípico, sem nenhuma consequência legal"],"explicacao":"Art. 28, § 1º, da Lei 11.343/2006."},{"id":2556,"materia":"leg","nivel":1,"enunciado":"Pela Lei Maria da Penha, a violência patrimonial inclui:","opcoes":["Reter ou destruir documentos e bens da mulher","Apenas agressões físicas","Somente xingamentos","Apenas ameaças feitas por telefone ou mensagem"],"explicacao":"Art. 7º, IV, da Lei 11.340/2006."},{"id":2557,"materia":"leg","nivel":1,"enunciado":"Pela Lei Maria da Penha, as medidas protetivas de urgência são concedidas, em regra, pelo:","opcoes":["Juiz","Delegado, sempre","Conselho Tutelar","Promotor, sem juiz"],"explicacao":"Em casos excepcionais a lei permite o afastamento do lar por delegado ou policial."},{"id":2558,"materia":"leg","nivel":1,"enunciado":"Pelo ECA, adolescente é a pessoa entre:","opcoes":["12 e 18 anos incompletos","10 e 16 anos","14 e 21 anos","12 e 16 anos"],"explicacao":"Criança tem até 12 anos incompletos."},{"id":2559,"materia":"leg","nivel":1,"enunciado":"Pelo ECA, o Conselho Tutelar é um órgão:","opcoes":["Permanente, autônomo e não jurisdicional","Do Poder Judiciário","Da Polícia Civil","Temporário, criado pelo juiz para cada caso concreto"],"explicacao":"Art. 131 do ECA."},{"id":2560,"materia":"leg","nivel":1,"enunciado":"Pelo CTB, dirigir com 0,3 mg ou mais de álcool por litro de ar alveolar é:","opcoes":["Crime","Apenas infração leve","Permitido","Contravenção penal"],"explicacao":"Art. 306 do CTB."},{"id":2561,"materia":"inf","nivel":1,"enunciado":"No Excel, a função =MÉDIA(A1:A4) calcula:","opcoes":["A média aritmética dos valores","A soma dos valores","O maior valor encontrado no intervalo de células","A quantidade de células"],"explicacao":"Soma os valores e divide pela quantidade."},{"id":2562,"materia":"inf","nivel":1,"enunciado":"No Excel, a referência $A$1 é:","opcoes":["Absoluta","Relativa","Mista","Circular"],"explicacao":"O cifrão fixa a coluna e a linha ao copiar a fórmula."},{"id":2563,"materia":"inf","nivel":1,"enunciado":"Qual protocolo recebe e-mails mantendo-os sincronizados no servidor?","opcoes":["IMAP","SMTP","FTP","HTTP"],"explicacao":"SMTP envia; POP3 e IMAP recebem."},{"id":2564,"materia":"inf","nivel":1,"enunciado":"Ransomware é um malware que:","opcoes":["Sequestra dados e pede resgate","Mostra propagandas na tela sem pedir autorização","Acelera o computador","Só registra o que se digita"],"explicacao":"Costuma criptografar arquivos e exigir pagamento."},{"id":2565,"materia":"inf","nivel":1,"enunciado":"O firewall serve para:","opcoes":["Controlar o tráfego de rede permitido ou bloqueado","Remover vírus de arquivos","Aumentar a memória RAM","Criar backups automáticos"],"explicacao":"Ele filtra conexões; não substitui o antivírus."},{"id":2566,"materia":"inf","nivel":1,"enunciado":"No Excel, a função CONT.SE serve para:","opcoes":["Contar células que atendem a um critério","Somar os valores das células que atendem a um critério","Calcular a média de um intervalo","Arredondar números"],"explicacao":"Ex.: =CONT.SE(A1:A10;\">5\")."},{"id":2567,"materia":"rl","nivel":1,"enunciado":"Qual é a negação de “Todos os alunos passaram”?","opcoes":["Algum aluno não passou","Nenhum aluno passou","Todos os alunos reprovaram","Alguns alunos passaram"],"explicacao":"Basta um caso contrário para negar o “todos”."},{"id":2568,"materia":"rl","nivel":1,"enunciado":"Se hoje é segunda-feira, que dia será daqui a 10 dias?","opcoes":["Quinta-feira","Quarta-feira","Sexta-feira","Terça-feira"],"explicacao":"10 dias = 1 semana + 3 dias."},{"id":2569,"materia":"rl","nivel":1,"enunciado":"Quanto é 15% de 80?","opcoes":["12","15","10","8"],"explicacao":"0,15 × 80 = 12."},{"id":2570,"materia":"rl","nivel":1,"enunciado":"R$ 1.000 a juros compostos de 10% ao mês viram, após 2 meses:","opcoes":["R$ 1.210","R$ 1.200","R$ 1.100","R$ 1.020"],"explicacao":"1.000 × 1,1 × 1,1 = 1.210."},{"id":2571,"materia":"rl","nivel":1,"enunciado":"De quantas formas 4 pessoas podem se sentar em fila?","opcoes":["24","16","12","8"],"explicacao":"4! = 4 × 3 × 2 × 1 = 24."},{"id":2572,"materia":"rl","nivel":1,"enunciado":"Se x/3 = 7, então x vale:","opcoes":["21","10","4","24"],"explicacao":"x = 7 × 3."},{"id":2573,"materia":"est","nivel":1,"enunciado":"Qual a média de 2, 4, 6, 8 e 10?","opcoes":["6","5","8","4"],"explicacao":"Soma 30 ÷ 5 = 6."},{"id":2574,"materia":"est","nivel":1,"enunciado":"Lançando uma moeda honesta duas vezes, qual a probabilidade de sair cara nas duas?","opcoes":["1/4","1/2","1/3","3/4"],"explicacao":"1/2 × 1/2 = 1/4."},{"id":2575,"materia":"est","nivel":1,"enunciado":"Qual a mediana de 3, 8, 5 e 10?","opcoes":["6,5","5","8","6"],"explicacao":"Em ordem: 3, 5, 8, 10. Média dos centrais: (5 + 8) ÷ 2."},{"id":2576,"materia":"est","nivel":1,"enunciado":"O desvio padrão mede:","opcoes":["A dispersão dos dados em torno da média","O valor que aparece com mais frequência no conjunto","O valor central","A soma dos dados"],"explicacao":"Quanto maior, mais espalhados os dados."},{"id":2577,"materia":"est","nivel":1,"enunciado":"Numa urna com 3 bolas azuis e 7 vermelhas, a probabilidade de tirar uma azul é:","opcoes":["30%","70%","3%","33%"],"explicacao":"3 em 10 = 30%."},{"id":2578,"materia":"est","nivel":1,"enunciado":"O coeficiente de variação relaciona:","opcoes":["Desvio padrão e média","Moda e mediana","Máximo e mínimo","Frequência e amplitude"],"explicacao":"CV = desvio padrão ÷ média; permite comparar dispersões."},{"id":2579,"materia":"cont","nivel":1,"enunciado":"Um adiantamento recebido de cliente, antes de entregar a mercadoria, é registrado no:","opcoes":["Passivo","Ativo","Patrimônio líquido","Resultado, de imediato"],"explicacao":"A empresa deve a mercadoria ao cliente."},{"id":2580,"materia":"cont","nivel":1,"enunciado":"Um seguro pago antecipadamente, a vencer nos próximos meses, fica no:","opcoes":["Ativo","Passivo","Patrimônio líquido","Resultado, de uma vez"],"explicacao":"É despesa antecipada: vira despesa mês a mês."},{"id":2581,"materia":"cont","nivel":1,"enunciado":"A depreciação registra:","opcoes":["O desgaste de bens do imobilizado","A valorização de imóveis e terrenos ao longo do tempo","A perda de clientes","Os juros de empréstimos"],"explicacao":"Terrenos, em regra, não se depreciam."},{"id":2582,"materia":"cont","nivel":1,"enunciado":"A provisão para férias dos empregados é registrada no:","opcoes":["Passivo","Ativo","Patrimônio líquido","Imobilizado"],"explicacao":"É uma obrigação da empresa com os empregados."},{"id":2583,"materia":"cont","nivel":1,"enunciado":"Receitas maiores que despesas no período geram:","opcoes":["Lucro","Prejuízo","Passivo a descoberto","Depreciação"],"explicacao":"O lucro aumenta o patrimônio líquido."},{"id":2584,"materia":"cont","nivel":1,"enunciado":"A demonstração que apresenta o resultado do exercício é a:","opcoes":["DRE","DFC","DMPL","Balanço Patrimonial"],"explicacao":"Demonstração do Resultado do Exercício."},{"id":2585,"materia":"dh","nivel":1,"enunciado":"O sistema global de proteção dos direitos humanos é coordenado pela:","opcoes":["ONU","OEA","OTAN","OMC"],"explicacao":"Os sistemas regionais incluem o interamericano, da OEA."},{"id":2586,"materia":"dh","nivel":1,"enunciado":"Pela Constituição, o preso tem direito à identificação dos responsáveis:","opcoes":["Por sua prisão ou por seu interrogatório policial","Por sua defesa técnica no processo penal que responde","Por sua alimentação","Por seu transporte"],"explicacao":"Art. 5º, LXIV."},{"id":2587,"materia":"dh","nivel":1,"enunciado":"A Lei 7.716/1989 define os crimes resultantes de:","opcoes":["Preconceito de raça ou de cor","Abuso de autoridade","Tortura","Violência doméstica"],"explicacao":"É a Lei do Racismo."},{"id":2588,"materia":"dh","nivel":1,"enunciado":"A Convenção Americana proíbe aplicar pena de morte a quem, na época do crime, tinha menos de:","opcoes":["18 anos","21 anos","16 anos","14 anos"],"explicacao":"Também a maiores de 70 anos e a mulheres grávidas (art. 4º)."},{"id":2589,"materia":"dh","nivel":1,"enunciado":"Pela Constituição, pode-se entrar na casa sem consentimento do morador, entre outros casos:","opcoes":["Em flagrante delito, a qualquer hora","Por ordem escrita do delegado, durante a noite","Para fiscalização de rotina","Por ordem verbal de policial"],"explicacao":"Por ordem judicial, só durante o dia (art. 5º, XI)."},{"id":2590,"materia":"dh","nivel":1,"enunciado":"O Brasil reconheceu a jurisdição obrigatória da Corte Interamericana em:","opcoes":["1998","1992","1988","2005"],"explicacao":"Pelo Decreto Legislativo 89/1998."},{"id":2591,"materia":"civ","nivel":1,"enunciado":"A compra e venda fica perfeita quando as partes concordam sobre:","opcoes":["A coisa e o preço","O prazo de garantia","O registro em cartório","O nome do tabelião"],"explicacao":"Art. 482 do Código Civil."},{"id":2592,"materia":"civ","nivel":1,"enunciado":"A propriedade dos bens móveis se transfere, em regra, com a:","opcoes":["Tradição (entrega da coisa)","Escritura pública","Assinatura do contrato, mesmo sem entrega da coisa","Publicação no jornal"],"explicacao":"Imóveis se transferem pelo registro."},{"id":2593,"materia":"civ","nivel":1,"enunciado":"O devedor que não paga no tempo, no lugar e na forma combinados está em:","opcoes":["Mora","Compensação","Novação","Remissão"],"explicacao":"A mora gera juros e outras consequências."},{"id":2594,"materia":"civ","nivel":1,"enunciado":"O perdão de uma dívida pelo credor chama-se:","opcoes":["Remissão","Remição","Novação","Dação"],"explicacao":"Remissão é perdão; remição é resgate."},{"id":2595,"materia":"civ","nivel":1,"enunciado":"Entregar ao credor, com o acordo dele, coisa diferente da devida para quitar a dívida é a:","opcoes":["Dação em pagamento","Compensação","Confusão","Consignação"],"explicacao":"Art. 356 do Código Civil."},{"id":2596,"materia":"civ","nivel":1,"enunciado":"Quando credor e devedor passam a ser a mesma pessoa, a obrigação se extingue por:","opcoes":["Confusão","Compensação","Novação","Transação"],"explicacao":"Ex.: o devedor herda o crédito do credor."},{"id":2597,"materia":"pciv","nivel":1,"enunciado":"Em regra, o prazo para contestar começa a contar da:","opcoes":["Audiência de conciliação sem acordo","Data do ajuizamento","Sentença","Citação do autor"],"explicacao":"Art. 335, I, do CPC."},{"id":2598,"materia":"pciv","nivel":1,"enunciado":"As causas em que a União é parte são julgadas, em regra, pela:","opcoes":["Justiça Federal","Justiça Estadual","Justiça do Trabalho","Justiça Eleitoral"],"explicacao":"Art. 109, I, da CF."},{"id":2599,"materia":"pciv","nivel":1,"enunciado":"As ações de divórcio e de alimentos são julgadas, em regra, na:","opcoes":["Vara de família","Vara criminal","Justiça Federal","Vara da Fazenda Pública"],"explicacao":"São causas de direito de família."},{"id":2600,"materia":"pciv","nivel":1,"enunciado":"O agravo de instrumento é interposto diretamente no:","opcoes":["Tribunal","Juízo de primeiro grau","STF","Cartório distribuidor"],"explicacao":"Art. 1.016 do CPC."},{"id":2601,"materia":"pciv","nivel":1,"enunciado":"Os embargos à execução servem para:","opcoes":["O executado se defender na execução de título extrajudicial","O autor pedir mais provas e ampliar o pedido inicial","Recorrer de sentença ao STF","Pedir a prisão do devedor"],"explicacao":"Art. 914 do CPC."},{"id":2602,"materia":"pciv","nivel":1,"enunciado":"O cumprimento de sentença serve para:","opcoes":["Fazer valer o que a sentença decidiu","Abrir um novo processo de conhecimento","Recorrer da sentença","Anular a citação"],"explicacao":"É a fase de satisfação do direito reconhecido."},{"id":2603,"materia":"trib","nivel":1,"enunciado":"O princípio que proíbe cobrar tributo sobre fatos anteriores à lei que o criou é a:","opcoes":["Irretroatividade","Anterioridade","Isonomia","Capacidade contributiva"],"explicacao":"Art. 150, III, a, da CF."},{"id":2604,"materia":"trib","nivel":1,"enunciado":"Pela isonomia tributária, é proibido:","opcoes":["Tratar de forma desigual contribuintes em situação equivalente","Cobrar impostos progressivos conforme o valor dos bens","Conceder isenções por lei","Cobrar taxas"],"explicacao":"Art. 150, II, da CF."},{"id":2605,"materia":"trib","nivel":1,"enunciado":"Sempre que possível, os impostos serão graduados conforme a:","opcoes":["Capacidade econômica do contribuinte","Vontade do fiscal","Profissão do contribuinte","Localização do cartório"],"explicacao":"Art. 145, § 1º: capacidade contributiva."},{"id":2606,"materia":"trib","nivel":1,"enunciado":"O IPI é um imposto:","opcoes":["Seletivo, conforme a essencialidade do produto","Progressivo conforme a renda do comprador final","Cobrado pelos municípios","Que incide sobre serviços"],"explicacao":"Produtos supérfluos podem ter alíquota maior."},{"id":2607,"materia":"trib","nivel":1,"enunciado":"O imposto de renda segue os critérios da generalidade, da universalidade e da:","opcoes":["Progressividade","Seletividade","Regressividade","Cumulatividade"],"explicacao":"Art. 153, § 2º, I, da CF."},{"id":2608,"materia":"trib","nivel":1,"enunciado":"As contribuições de interesse das categorias profissionais são de competência:","opcoes":["Da União","Dos estados","Dos municípios","Dos conselhos, sem lei"],"explicacao":"Art. 149 da CF."},{"id":2609,"materia":"afo","nivel":1,"enunciado":"A LDO orienta a elaboração da:","opcoes":["LOA","Constituição","Lei de Responsabilidade Fiscal","Lei 4.320/1964"],"explicacao":"Art. 165, § 2º, da CF."},{"id":2610,"materia":"afo","nivel":1,"enunciado":"Na União, o projeto da LOA deve ser devolvido para sanção até:","opcoes":["O encerramento da sessão legislativa","15 de abril","31 de agosto","30 de junho"],"explicacao":"ADCT, art. 35, § 2º, III."},{"id":2611,"materia":"afo","nivel":1,"enunciado":"O princípio orçamentário do equilíbrio busca que:","opcoes":["As despesas não superem as receitas","As receitas sejam vinculadas","O orçamento dure 4 anos","Não haja publicidade"],"explicacao":"É reforçado pela LRF."},{"id":2612,"materia":"afo","nivel":1,"enunciado":"Pelo princípio da especificação, as despesas devem ser:","opcoes":["Discriminadas de forma detalhada","Agrupadas em um único valor global","Mantidas em sigilo","Aprovadas pelo Judiciário"],"explicacao":"Proíbe dotações globais sem detalhamento."},{"id":2613,"materia":"afo","nivel":1,"enunciado":"O orçamento-programa tem como foco:","opcoes":["Os objetivos e resultados das ações","Apenas o controle contábil","A lista detalhada de compras de material do ano","O salário dos parlamentares"],"explicacao":"Liga os gastos às metas do governo."},{"id":2614,"materia":"afo","nivel":1,"enunciado":"Pela LRF, o Relatório de Gestão Fiscal deve ser assinado, entre outros, pelo:","opcoes":["Chefe do Poder","Presidente de banco","Tesoureiro de partido","Auditor privado"],"explicacao":"Art. 54 da LRF."},{"id":2615,"materia":"gest","nivel":1,"enunciado":"A departamentalização funcional agrupa as atividades por:","opcoes":["Especialidade ou função","Região geográfica","Cliente atendido","Projeto temporário"],"explicacao":"Ex.: setores de finanças, pessoal e compras."},{"id":2616,"materia":"gest","nivel":1,"enunciado":"A departamentalização geográfica agrupa as atividades por:","opcoes":["Localização ou território","Produto","Cliente","Função"],"explicacao":"Ex.: superintendências regionais."},{"id":2617,"materia":"gest","nivel":1,"enunciado":"Para McGregor, a Teoria Y vê o trabalhador como alguém que:","opcoes":["Gosta de trabalhar e busca responsabilidade","Evita o trabalho e precisa ser controlado o tempo todo","Só se motiva pelo salário","Não aceita mudanças"],"explicacao":"A Teoria X é a visão pessimista."},{"id":2618,"materia":"gest","nivel":1,"enunciado":"A liderança democrática se caracteriza por:","opcoes":["Decisões discutidas com o grupo","Decisões impostas pelo líder","Ausência total de liderança","Controle por punições"],"explicacao":"A liberal (laissez-faire) deixa o grupo à vontade."},{"id":2619,"materia":"gest","nivel":1,"enunciado":"A transparência ativa ocorre quando o órgão:","opcoes":["Divulga informações por iniciativa própria","Responde só quando alguém faz um pedido formal","Esconde dados sensíveis","Cobra para dar informações"],"explicacao":"Responder a pedidos é transparência passiva."},{"id":2620,"materia":"gest","nivel":1,"enunciado":"O controle concomitante ocorre:","opcoes":["Durante a execução da atividade","Antes do início da atividade","Somente depois de concluída","Apenas uma vez por ano"],"explicacao":"O preventivo vem antes; o posterior, depois."},{"id":2621,"materia":"arq","nivel":1,"enunciado":"A eliminação de documentos deve ser registrada em:","opcoes":["Termo de eliminação","Boletim de ocorrência","Nota fiscal","Ata de assembleia"],"explicacao":"O termo registra o que foi eliminado e quando."},{"id":2622,"materia":"arq","nivel":1,"enunciado":"No método numérico cronológico, além do número, considera-se:","opcoes":["A data","A cor","O peso","O autor"],"explicacao":"É o método usado em muitos protocolos."},{"id":2623,"materia":"arq","nivel":1,"enunciado":"Um fundo fechado pertence a um órgão que:","opcoes":["Foi extinto e não produz mais documentos","Continua em plena atividade, produzindo documentos","Só produz documentos digitais","Ainda não foi criado"],"explicacao":"No fundo aberto, o órgão continua produzindo."},{"id":2624,"materia":"arq","nivel":1,"enunciado":"Documentos de valor permanente não podem ser:","opcoes":["Eliminados","Consultados","Digitalizados","Descritos"],"explicacao":"Lei 8.159/1991, art. 10."},{"id":2625,"materia":"arq","nivel":1,"enunciado":"Um documento digital autêntico é aquele que:","opcoes":["É o que diz ser, sem adulteração","Foi impresso em papel timbrado e carimbado pelo setor","Tem muitas cópias","Foi enviado por e-mail"],"explicacao":"Autenticidade envolve identidade e integridade."},{"id":2626,"materia":"arq","nivel":1,"enunciado":"O acondicionamento adequado de documentos usa:","opcoes":["Caixas e pastas de material neutro","Sacos plásticos bem fechados para evitar a poeira","Caixas de papelão de mercado","Envelopes com clipes de metal"],"explicacao":"Materiais ácidos e metais aceleram a deterioração."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes));
select nivel, count(*) as questoes from public.questoes group by nivel order by nivel;
